"""Developer, operations, moderation, and governance operations."""

from __future__ import annotations

from .common import IDEMPOTENCY_KEY, LIMIT20, OperationAdder, array, async_acceptance_response, json_body, p, path_parameter, query_parameter, ref, response, string


def add_operations(add: OperationAdder) -> None:
    """Add this operation family to the contract path catalog."""
    # Platform routes, ordered by path and HTTP method.
    add("/admin/account-deletions", "get", operation_id="listDeadLetteredAccountDeletions", tag="Admin operations", summary="Inspect dead-lettered account deletions", description="Returns DEAD_LETTERED account-deletion sagas oldest first by the time the current status was last updated. The bounded page defaults to 20 and accepts 1–100 items. Pass both afterUpdatedAt and afterSagaId from nextCursor to continue. This read-only endpoint never retries cleanup; use the saga detail route to inspect current steps before an explicit operator resolution. Because sagas can transition into or out of DEAD_LETTERED while paging, this is not a frozen snapshot.", success_schema="DeadLetteredUserDeletionListResponse", security="admin", parameters=[LIMIT20, query_parameter("afterUpdatedAt", "Updated-at value from the previous page cursor", string(format="date-time")), query_parameter("afterSagaId", "Saga ID from the previous page cursor", string(format="uuid"))])
    add("/admin/account-deletions/{saga_id}", "get", operation_id="getAccountDeletionSaga", tag="Admin operations", summary="Inspect one account-deletion saga", description="Returns the current persisted saga and ordered cleanup-step states for an administrator. This is a read-only status lookup; a saga can change while it is being inspected. A missing saga returns 404.", success_schema="UserDeletionSaga", security="admin", parameters=[p("saga_id")], extra_responses={"404": response("The saga does not exist", "ErrorResponse")})
    add("/admin/account-deletions/{saga_id}/retry", "post", operation_id="retryDeadLetteredAccountDeletion", tag="Admin operations", summary="Authorize retry of a dead-lettered account deletion", description="Only a DEAD_LETTERED saga can be restarted. Requires a client-generated resolutionId reused with the exact same request after an uncertain response, a reason, and an identifier for a protected evidence record. The reference is syntax-checked, not resolved externally; do not include secrets or evidence contents. AuthService atomically records an immutable resolution receipt and reviewer-attributed audit event, starts a fresh bounded attempt cycle for incomplete steps, and fences results from older worker generations. Reusing the resolution ID with different request values conflicts. The 202 response reports the saga's current state; acceptance does not mean cleanup is complete. The attempt ceiling is deployment-configured and total administrator retry cycles are not globally capped.", success_schema="UserDeletionRetryAcceptedResponse", success_status="202", security="admin", request_body=json_body("RetryUserDeletionRequest"), parameters=[p("saga_id")], extra_responses={"409": response("The saga is not dead-lettered or the resolution ID conflicts with a prior request", "ErrorResponse")})
    add("/admin/clients", "get", operation_id="listClientProfiles", tag="Admin governance", summary="List client profiles", success_schema=array(ref("ClientProfile")), security="admin")
    add("/admin/clients", "post", operation_id="createClientProfile", tag="Admin governance", summary="Create a client profile", success_schema="ClientProfile", success_status="201", security="admin", request_body=json_body("ClientProfileRequest"))
    add("/admin/clients/{client_id}", "get", operation_id="getClientProfile", tag="Admin governance", summary="Get a client profile", success_schema="ClientProfile", security="admin", parameters=[p("client_id")])
    add("/admin/contracts", "get", operation_id="listRouteContracts", tag="Admin governance", summary="List route contracts", success_schema=array(ref("RouteContract")), security="admin")
    add("/admin/contracts", "post", operation_id="createRouteContract", tag="Admin governance", summary="Create a route contract", success_schema="RouteContract", success_status="201", security="admin", request_body=json_body("RouteContractCreateRequest"))
    add("/admin/contracts/{contract_id}", "get", operation_id="getRouteContract", tag="Admin governance", summary="Get a route contract", success_schema="RouteContract", security="admin", parameters=[p("contract_id")])
    add("/admin/contracts/{contract_id}/versions", "get", operation_id="listRouteContractVersions", tag="Admin governance", summary="List route contract versions", success_schema=array(ref("RouteContractVersion")), security="admin", parameters=[p("contract_id")])
    add("/admin/contracts/{contract_id}/versions", "post", operation_id="createRouteContractVersion", tag="Admin governance", summary="Create a route contract version", success_schema="RouteContractVersion", success_status="201", security="admin", request_body=json_body("RouteContractVersionCreateRequest"), parameters=[p("contract_id")])
    add("/admin/contracts/{contract_id}/versions/{version}", "get", operation_id="getRouteContractVersion", tag="Admin governance", summary="Get a route contract version", success_schema="RouteContractVersion", security="admin", parameters=[p("contract_id"), path_parameter("version", "Contract version")])
    add("/admin/contracts/{contract_id}/versions/{version}", "patch", operation_id="updateRouteContractVersion", tag="Admin governance", summary="Update a route contract version", success_schema="RouteContractVersion", security="admin", request_body=json_body("RouteContractVersionUpdateRequest"), parameters=[p("contract_id"), path_parameter("version", "Contract version")])
    add("/admin/moderation/content-decisions", "get", operation_id="listContentModerationDecisionStatus", tag="Admin moderation", summary="Inspect pending, unavailable, and retry-exhausted content decisions", description="Returns pending, terminal TARGET_UNAVAILABLE, and RETRY_EXHAUSTED content-decision outbox records in oldest-first order. Pass both afterCreatedAt and afterReportId from nextCursor to continue; this read-only endpoint does not retry or resolve work.", success_schema="ModerationContentDecisionListResponse", security="admin", parameters=[LIMIT20, query_parameter("afterCreatedAt", "Created-at value from the previous page cursor", string(format="date-time")), query_parameter("afterReportId", "Report ID from the previous page cursor", string(format="uuid"))])
    add("/admin/moderation/content-decisions/{report_id}/replay", "post", operation_id="replayDeadLetteredContentModerationDecision", tag="Admin moderation", summary="Authorize replay of an exhausted content decision", description="Only RETRY_EXHAUSTED commands can be replayed. Requires a client-generated resolutionId reused with identical request fields after an uncertain response, a reason, and an identifier for a protected evidence record. The reference is syntax-checked but not resolved against an external evidence system. The Gateway appends an immutable reviewer-attributed audit record and requeues the original decision with a fresh attempt cycle; it does not change the decision payload or bypass PostService idempotency. Each cycle is limited to eight attempts; the total number of admin-authorized cycles is not capped.", success_schema="ContentDecisionReplayAcceptedResponse", success_status="202", security="admin", request_body=json_body("ReplayContentDecisionRequest"), parameters=[p("report_id")], extra_responses={"409": response("The decision is not retry-exhausted or the resolution ID conflicts with a prior replay", "ErrorResponse")})
    add("/admin/moderation/reports", "get", operation_id="listOpenModerationReports", tag="Admin moderation", summary="List open reports", success_schema="ModerationReportListResponse", security="admin", parameters=[LIMIT20])
    add("/admin/moderation/reports/{report_id}/decisions", "post", operation_id="createModerationDecision", tag="Admin moderation", summary="Record an immutable moderation decision", description="A pending content action cannot be superseded. If its target is unavailable, only DISMISS with a non-empty note can close the report; the immutable administrator decision and outbox resolution commit together.", success_schema="ModerationDecisionResponse", security="admin", request_body=json_body("CreateModerationDecisionRequest"), parameters=[p("report_id")])
    add("/admin/operations/{operation_id}", "get", operation_id="getOperationStatus", tag="Admin governance", summary="Resolve a durable operation by id", description="Returns the Gateway lifecycle state and its best evidence-backed outcome. For the ten allowlisted PostService, FriendService, ProfileService, and Gateway-owned moderation-report mutations, it also performs a read-only owner-receipt lookup. A verified complete receipt can resolve COMMITTED only when operation ID, actor, and versioned scope match the Gateway journal. NOT_FOUND is absence of evidence, not proof of non-commit; UNAVAILABLE, MISMATCH, and incomplete receipts remain unresolved. HTTP status alone never proves rejection: REJECTED_BEFORE_COMMIT requires evidence that an exact owner-backed route did not cross its mutation boundary or an audited manual resolution. The response contains receipt metadata only, not the actor ID, command, idempotency key, fingerprint, or outcome body. An unknown Gateway operation ID is a 404.", success_schema="OperationStatus", security="admin", parameters=[p("operation_id")])
    add("/admin/operations/{operation_id}/reconciliation", "post", operation_id="recordManualOperationReconciliation", tag="Admin governance", summary="Record an evidence-backed operation disposition", description="Appends an immutable, admin-attributed disposition for an UNKNOWN operation. Requires a reason and a reference to a protected evidence record. The Gateway journal is not rewritten, no response is manufactured, and the mutation is never rerun. Corrections must name the current resolution id and append a new revision. An identical retry by the same reviewer returns the existing record.", success_schema="ManualOperationResolution", success_status="201", security="admin", parameters=[p("operation_id")], request_body=json_body("ManualOperationResolutionRequest"), extra_responses={"200": response("The identical resolution request was already recorded", "ManualOperationResolution")})
    add("/admin/policies", "get", operation_id="listPolicies", tag="Admin governance", summary="List gateway policy sets", success_schema=array(ref("PolicySet")), security="admin")
    add("/admin/policies", "post", operation_id="createPolicy", tag="Admin governance", summary="Create a gateway policy set", success_schema="PolicySet", success_status="201", security="admin", request_body=json_body("PolicySetRequest"))
    add("/admin/policies/{policy_id}", "get", operation_id="getPolicy", tag="Admin governance", summary="Get a gateway policy set", success_schema="PolicySet", security="admin", parameters=[p("policy_id")])
    add("/admin/policies/{policy_id}", "put", operation_id="updatePolicy", tag="Admin governance", summary="Replace a gateway policy set", success_schema="PolicySet", security="admin", request_body=json_body("PolicySetRequest"), parameters=[p("policy_id")])
    add("/admin/post-events/dead-letters/{event_id}/replay", "post", operation_id="resolvePostEventDeadLetter", tag="Admin operations", summary="Authorize retry of a dead-lettered post event", description="Releases one unpublished dead-lettered aggregate head for the normal bounded outbox worker. Requires a client-generated resolutionId reused unchanged for retries, a reason, and a protected evidence reference. The PostService records the administrator and decision immutably before releasing the event; subsequent delivery attempts retain the resolution ID. It does not return or accept event payloads and does not allow skipping an event.", success_schema="DeadLetterReplayAcceptedResponse", success_status="202", security="admin", request_body=json_body("ResolveDeadLetterReplayRequest"), parameters=[p("event_id")])
    add("/admin/rollouts", "post", operation_id="createRollout", tag="Admin governance", summary="Create a rollout", success_schema="RolloutPolicy", success_status="201", security="admin", request_body=json_body("RolloutCreateRequest"))
    add("/admin/rollouts/{rollout_id}", "get", operation_id="getRollout", tag="Admin governance", summary="Get a rollout", success_schema="RolloutPolicy", security="admin", parameters=[p("rollout_id")])
    add("/admin/telemetry/summary", "get", operation_id="getTelemetrySummary", tag="Admin governance", summary="Get bounded gateway telemetry summary", success_schema="TelemetrySummary", security="admin")
    add("/api/aggregate/{route_key}", "get", operation_id="aggregateRoute", tag="Gateway aggregation", summary="Execute a configured aggregation recipe", success_schema="AggregationResponse", parameters=[path_parameter("route_key", "Route contract key")])
    add("/api/moderation/reports", "post", operation_id="createModerationReport", tag="Moderation", summary="Report a user, post, or comment", success_schema="ModerationReport", success_status="201", success_headers=("OperationId", "IdempotencyReplayed"), request_body=json_body("CreateReportRequest"), parameters=[IDEMPOTENCY_KEY], description="Optional Idempotency-Key replays the identical report creation from a Gateway-owned PostgreSQL receipt for 24 hours. The report and immutable versioned receipt snapshot commit in one transaction; after expiry the key tombstone remains and the result is not redispatched. When durable async execution is enabled, a timed-out keyed command may return 202 after queue acceptance.", extra_responses={"202": async_acceptance_response()})
    add("/api/moderation/reports/me", "get", operation_id="listMyModerationReports", tag="Moderation", summary="List reports created by the current user", success_schema="ModerationReportListResponse", parameters=[LIMIT20])
    add("/api/operations/{operation_id}", "get", operation_id="getOwnOperationStatus", tag="Operations", summary="Check your durable operation", description="Returns the authenticated caller's lifecycle state, evidence-backed outcome, response status, timestamps, and whether a response snapshot remains replayable. The lookup is actor-scoped; another caller's operation is indistinguishable from an unknown id. UNKNOWN does not prove rejection and does not authorize a new command. For a documented idempotency-enabled mutation, preserve the original key and payload; use only that operation's documented recovery path. The endpoint never returns the stored response, request details, owner-receipt data, or operator evidence.", success_schema="CallerOperationStatus", security="user", parameters=[p("operation_id")], extra_responses={"200": response("Operation status", "CallerOperationStatus", headers=("CacheControl",))})
    add(
        "/docs",
        "get",
        operation_id="getDeveloperPortal",
        tag="Developer",
        summary="Developer portal index",
        success_schema=string(),
        success_media_type="text/html",
        security="none",
        success_description="HTML developer portal",
    )
    add(
        "/openapi.json",
        "get",
        operation_id="getOpenApiContract",
        tag="Developer",
        summary="Raw OpenAPI 3.1 contract",
        success_schema="OpenApiDocument",
        security="none",
        success_description="OpenAPI JSON document",
    )
